#include <iostream>
#include <vector>

int sum(const std::vector<int>& numbers) {  // const reference to avoid copying and ensure immutability
    int total = 0;
    for (const auto& num : numbers) {  // Using const auto& for loop elements to prevent modification
        total += num;
    }
    return total;
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    std::cout << "The sum is: " << sum(data) << std::endl;  // Passing by const reference
    return 0;
}
